import"./chunk-VC46IEJQ.js";var a=(s,t)=>({en:s,zh:t}),e=(s,t,o,i,n,l,d,h,r)=>({name:a(...s),desc:a(...t),tour:a(...o),...r?{spoiler:a(...r)}:{},source:{confidence:i,refs:n,book:a(...l),unknown:a(...d),interpretation:a(...h)}}),u={id:"yunkai",intro:{en:"The Yellow City of Slaver's Bay, built of yellow brick and ruled by the Wise Masters, who are best known for training bed slaves. This scene imagines it as a tidy grid on a low hill, crowded with pyramids.",zh:"\u5974\u96B6\u6E7E\u7684\u9EC4\u57CE\uFF0C\u4EE5\u9EC4\u7816\u7B51\u6210\uFF0C\u7531\u667A\u8005\u7EDF\u6CBB\uFF0C\u5C24\u4EE5\u8C03\u6559\u5E8A\u5974\u95FB\u540D\u3002\u672C\u573A\u666F\u5C06\u5B83\u60F3\u8C61\u6210\u77EE\u4E18\u4E0A\u4E00\u5EA7\u89C4\u6574\u7684\u68CB\u76D8\u5F0F\u57CE\u5E02\uFF0C\u91D1\u5B57\u5854\u6797\u7ACB\u3002"},notes:{en:"From the books: the yellow brick that names the city, its walls and stepped pyramids, the Wise Masters, the bed-slave trade, a harpy above the gates, and an army camped before the walls. Invented here: the rectangular plan, grid streets, bastions, hill, pyramid positions, courtyard houses, gates and harbour. The books describe Yunkai far less than Meereen.",zh:"\u4E66\u4E2D\u53EF\u636E\uFF1A\u8D4B\u4E88\u57CE\u540D\u7684\u9EC4\u7816\u3001\u57CE\u5899\u4E0E\u9636\u68AF\u91D1\u5B57\u5854\u3001\u667A\u8005\u3001\u5E8A\u5974\u8D38\u6613\u3001\u57CE\u95E8\u4E0A\u65B9\u7684\u9E70\u8EAB\u5973\u5996\uFF0C\u4EE5\u53CA\u57CE\u4E0B\u624E\u8425\u7684\u5927\u519B\u3002\u672C\u573A\u666F\u81EA\u62DF\uFF1A\u957F\u65B9\u5F62\u5E73\u9762\u3001\u68CB\u76D8\u8857\u9053\u3001\u68F1\u5821\u3001\u77EE\u4E18\u3001\u91D1\u5B57\u5854\u4F4D\u7F6E\u3001\u5EAD\u9662\u9986\u820D\u3001\u57CE\u95E8\u4E0E\u6E2F\u53E3\u3002\u4E66\u4E2D\u5BF9\u6E0A\u51EF\u7684\u63CF\u5199\u8FDC\u5C11\u4E8E\u5F25\u6797\u3002"},tour:["land-gate","yellow-walls","besiegers-plain","slave-market","pyramid-hill","bed-slave-houses","lower-town","sea-gate","harbour","fishermens-quarter"],sources:[{ref:"asos",checked:"memory",note:a("Yunkai's walls, the Wise Masters and Daenerys's camp before the city come from A Storm of Swords; recalled, not re-read.","\u6E0A\u51EF\u7684\u57CE\u5899\u3001\u667A\u8005\uFF0C\u4EE5\u53CA\u4E39\u59AE\u8389\u4E1D\u5728\u57CE\u5916\u7684\u8425\u5730\uFF0C\u89C1\u4E8E\u300A\u51B0\u96E8\u7684\u98CE\u66B4\u300B\uFF1B\u51ED\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u539F\u6587\u3002")},{ref:"awoiaf",checked:"search-snippet",note:a("Search summaries of the wiki: yellow brick, crumbling walls, towers and stepped pyramids (one golden pyramid, of Qaggaz), a harpy above the gates, the Wise Masters and the bed-slave trade. Pages could not be fetched.","\u7ECF\u7EF4\u57FA\u641C\u7D22\u6458\u8981\u5370\u8BC1\uFF1A\u9EC4\u7816\u3001\u6B8B\u7834\u7684\u57CE\u5899\u3001\u5854\u697C\u4E0E\u9636\u68AF\u91D1\u5B57\u5854\uFF08\u5176\u4E2D\u6709\u5361\u52A0\u5179\u5BB6\u65CF\u7684\u91D1\u8272\u91D1\u5B57\u5854\uFF09\u3001\u57CE\u95E8\u4E0A\u65B9\u7684\u9E70\u8EAB\u5973\u5996\u3001\u667A\u8005\uFF0C\u4EE5\u53CA\u5E8A\u5974\u8D38\u6613\u3002\u9875\u9762\u672C\u8EAB\u65E0\u6CD5\u6253\u5F00\u3002")},{ref:"adwd",checked:"not-accessed",note:a("Later events (Yunkai returns to slavery and marches on Meereen) are not used for the scene.","\u540E\u7EED\u4E8B\u4EF6\uFF08\u6E0A\u51EF\u6062\u590D\u5974\u96B6\u5236\u5E76\u8FDB\u519B\u5F25\u6797\uFF09\u672A\u7528\u4E8E\u672C\u573A\u666F\u3002")}],landmarks:{"yellow-walls":e(["Yellow Walls","\u9EC4\u7816\u57CE\u5899"],["Walls of yellow brick with round, domed bastions at regular intervals.","\u9EC4\u7816\u57CE\u5899\uFF0C\u6BCF\u9694\u4E00\u6BB5\u4FBF\u6709\u4E00\u5EA7\u5706\u9876\u5706\u5F62\u68F1\u5821\u3002"],["The yellow brick gives the city both its colour and its name.","\u9EC4\u7816\u8D4B\u4E88\u8FD9\u5EA7\u57CE\u989C\u8272\uFF0C\u4E5F\u8D4B\u4E88\u5B83\u540D\u5B57\u3002"],"high",["asos","awoiaf"],["The city and its walls are of yellow brick; the walls are described as old and crumbling.","\u57CE\u5E02\u4E0E\u57CE\u5899\u7686\u4EE5\u9EC4\u7816\u780C\u6210\uFF1B\u57CE\u5899\u88AB\u63CF\u8FF0\u4E3A\u53E4\u65E7\u6B8B\u7834\u3002"],["Wall height, thickness and number of towers.","\u57CE\u5899\u9AD8\u5EA6\u3001\u539A\u5EA6\u4E0E\u5854\u697C\u6570\u91CF\u3002"],["A straight-sided rectangle with a round bastion every 26 units; the domes are invented, and the walls are drawn intact rather than crumbling.","\u57CE\u5899\u5448\u957F\u65B9\u5F62\uFF0C\u6BCF\u9694\u4E8C\u5341\u516D\u5355\u4F4D\u8BBE\u4E00\u5EA7\u5706\u5F62\u68F1\u5821\uFF1B\u5706\u9876\u4E3A\u81EA\u62DF\uFF0C\u57CE\u5899\u4E5F\u753B\u5F97\u6BD4\u4E66\u4E2D\u5B8C\u6574\u3002"]),"land-gate":e(["West Gate","\u897F\u95E8"],["The gate facing the plain, flanked by two domed towers.","\u9762\u5411\u5E73\u539F\u7684\u57CE\u95E8\uFF0C\u4E24\u4FA7\u5404\u6709\u4E00\u5EA7\u5706\u9876\u5854\u3002"],["An army camped before this gate could study the walls it would have to take.","\u5728\u6B64\u95E8\u524D\u624E\u8425\u7684\u5927\u519B\uFF0C\u53EF\u4EE5\u7EC6\u770B\u81EA\u5DF1\u5C06\u8981\u653B\u6253\u7684\u57CE\u5899\u3002"],"low",["asos","awoiaf"],["A harpy is said to stand above the city's gates; no gate is described in detail.","\u636E\u8F7D\u57CE\u95E8\u4E0A\u65B9\u7ACB\u6709\u9E70\u8EAB\u5973\u5996\uFF1B\u6CA1\u6709\u54EA\u5EA7\u57CE\u95E8\u5F97\u5230\u5177\u4F53\u63CF\u5199\u3002"],["Number, form and names of the gates.","\u57CE\u95E8\u7684\u6570\u91CF\u3001\u5F62\u5236\u4E0E\u540D\u79F0\u3002"],["Four gates, the west and east ones larger; all designed here.","\u5171\u56DB\u5EA7\u57CE\u95E8\uFF0C\u4E1C\u897F\u4E24\u95E8\u8F83\u5927\uFF1B\u5747\u4E3A\u672C\u573A\u666F\u8BBE\u8BA1\u3002"]),"sea-gate":e(["Sea Gate","\u6D77\u95E8"],["The broad eastern gate that opens onto the quays.","\u901A\u5F80\u7801\u5934\u7684\u4E1C\u4FA7\u5BBD\u9614\u57CE\u95E8\u3002"],["Cargo, captives and sailors pass through this gate to the harbour.","\u8D27\u7269\u3001\u4FD8\u864F\u4E0E\u6C34\u624B\u7ECF\u7531\u6B64\u95E8\u5F80\u6765\u6E2F\u53E3\u3002"],"low",["asos"],["Yunkai lies on the bay; a sea gate is not described.","\u6E0A\u51EF\u6FD2\u4E34\u6D77\u6E7E\uFF1B\u4E66\u4E2D\u5E76\u672A\u63CF\u5199\u6D77\u95E8\u3002"],["Everything about a sea gate.","\u5173\u4E8E\u6D77\u95E8\u7684\u4E00\u5207\u3002"],["The whole structure is invented as a counterpart to the west gate.","\u6574\u5EA7\u57CE\u95E8\u4E3A\u81EA\u62DF\uFF0C\u4E0E\u897F\u95E8\u76F8\u5BF9\u5E94\u3002"]),"pyramid-hill":e(["Pyramid Hill","\u91D1\u5B57\u5854\u4E18"],["A low hill crowned by the tallest pyramid and ringed by lesser ones, homes of the Wise Masters.","\u77EE\u4E18\u9876\u4E0A\u662F\u6700\u9AD8\u7684\u91D1\u5B57\u5854\uFF0C\u56DB\u5468\u73AF\u7ED5\u7740\u8F83\u5C0F\u7684\u91D1\u5B57\u5854\uFF0C\u90FD\u662F\u667A\u8005\u7684\u5B85\u90B8\u3002"],["The Wise Masters live in stepped pyramids of yellow brick, one of them golden.","\u667A\u8005\u4EEC\u4F4F\u5728\u9EC4\u7816\u780C\u6210\u7684\u9636\u68AF\u91D1\u5B57\u5854\u91CC\uFF0C\u5176\u4E2D\u4E00\u5EA7\u5448\u91D1\u8272\u3002"],"medium",["asos","awoiaf"],["Yunkai has tall stepped pyramids, including the golden pyramid of Qaggaz.","\u6E0A\u51EF\u6709\u9AD8\u8038\u7684\u9636\u68AF\u91D1\u5B57\u5854\uFF0C\u5176\u4E2D\u5305\u62EC\u5361\u52A0\u5179\u5BB6\u65CF\u7684\u91D1\u8272\u91D1\u5B57\u5854\u3002"],["Their number, size and distribution; there is no evidence of a hill.","\u6570\u91CF\u3001\u5927\u5C0F\u4E0E\u5206\u5E03\uFF1B\u5E76\u65E0\u57CE\u4E2D\u6709\u4E18\u7684\u4F9D\u636E\u3002"],["Eight pyramids, the tallest on an invented central hill.","\u516B\u5EA7\u91D1\u5B57\u5854\uFF0C\u6700\u9AD8\u8005\u7ACB\u4E8E\u81EA\u62DF\u7684\u57CE\u4E2D\u77EE\u4E18\u4E0A\u3002"]),"bed-slave-houses":e(["Bed-Slave Houses","\u5E8A\u5974\u9986"],["Courtyard houses with gardens where bed slaves are trained.","\u5E26\u82B1\u56ED\u7684\u5EAD\u9662\u9986\u820D\uFF0C\u5E8A\u5974\u5728\u6B64\u53D7\u8BAD\u3002"],["Yunkai is known for its trained bed slaves; these houses are imagined.","\u6E0A\u51EF\u4EE5\u53D7\u8FC7\u8C03\u6559\u7684\u5E8A\u5974\u95FB\u540D\uFF1B\u8FD9\u4E9B\u9986\u820D\u51FA\u4E8E\u60F3\u8C61\u3002"],"low",["asos","awoiaf"],["Training bed slaves is Yunkai's speciality; where it happens is not described.","\u8C03\u6559\u5E8A\u5974\u662F\u6E0A\u51EF\u7684\u4E13\u957F\uFF1B\u5728\u4F55\u5904\u8FDB\u884C\uFF0C\u4E66\u4E2D\u672A\u8FF0\u3002"],["Their layout, number and location.","\u5E03\u5C40\u3001\u6570\u91CF\u4E0E\u4F4D\u7F6E\u3002"],["Four square courtyard houses with palms and awnings; invented.","\u56DB\u5EA7\u65B9\u5F62\u5EAD\u9662\uFF0C\u914D\u68D5\u6988\u4E0E\u906E\u9633\u7BF7\uFF1B\u4E3A\u81EA\u62DF\u3002"]),"slave-market":e(["Slave Market","\u5974\u96B6\u5E02\u573A"],["A square of awnings and auction platforms.","\u4E00\u5904\u904D\u5E03\u906E\u9633\u68DA\u4E0E\u62CD\u5356\u53F0\u7684\u5E7F\u573A\u3002"],["People are sold here by the lot.","\u4EBA\u5728\u8FD9\u91CC\u88AB\u6210\u6279\u51FA\u552E\u3002"],"low",["asos"],["Yunkai is a slaving city; no market place is described.","\u6E0A\u51EF\u662F\u5974\u96B6\u8D38\u6613\u4E4B\u57CE\uFF1B\u4E66\u4E2D\u672A\u63CF\u5199\u5177\u4F53\u5E02\u573A\u3002"],["Whether there is a market square, and what it looks like.","\u662F\u5426\u6709\u5E02\u573A\u5E7F\u573A\uFF0C\u53C8\u662F\u4F55\u6A21\u6837\u3002"],["A market square in the west quarter; invented.","\u897F\u533A\u7684\u4E00\u5904\u5E02\u573A\u5E7F\u573A\uFF1B\u4E3A\u81EA\u62DF\u3002"]),harbour:e(["Harbour","\u6D77\u6E2F"],["A sheltered basin between two moles, with piers, cogs and galleys.","\u4E24\u9053\u9632\u6CE2\u5824\u4E4B\u95F4\u7684\u907F\u98CE\u6E2F\u6C60\uFF0C\u8BBE\u6709\u6808\u6865\uFF0C\u6CCA\u7740\u67EF\u514B\u8239\u4E0E\u6868\u5E06\u8239\u3002"],["Two long moles shelter the quays on Slaver's Bay.","\u4E24\u9053\u957F\u5824\u4E3A\u5974\u96B6\u6E7E\u7554\u7684\u7801\u5934\u6321\u4F4F\u98CE\u6D6A\u3002"],"low",["asos"],["The city lies on the bay; its harbour is not described.","\u57CE\u5E02\u6FD2\u4E34\u6D77\u6E7E\uFF1B\u6E2F\u53E3\u672A\u89C1\u63CF\u5199\u3002"],["Harbour shape and defences.","\u6E2F\u53E3\u5F62\u72B6\u4E0E\u9632\u5FA1\u3002"],["Moles, towers and four piers are all invented.","\u9632\u6CE2\u5824\u3001\u5854\u697C\u4E0E\u56DB\u5EA7\u6808\u6865\u5747\u4E3A\u81EA\u62DF\u3002"]),"fishermens-quarter":e(["Fishermen's Quarter","\u6E14\u6C11\u533A"],["Small houses, boats and drying nets along the shore north of the sea gate.","\u6D77\u95E8\u4EE5\u5317\u7684\u5CB8\u8FB9\uFF0C\u5C0F\u5C4B\u3001\u6E14\u8239\u4E0E\u667E\u6652\u7684\u6E14\u7F51\u3002"],["Humbler houses, and boats pulled up on the beach.","\u7B80\u964B\u7684\u5C4B\u820D\uFF0C\u62D6\u4E0A\u6C99\u6EE9\u7684\u5C0F\u8239\u3002"],"low",["asos"],["Not described in the books.","\u4E66\u4E2D\u672A\u63D0\u53CA\u3002"],["Everything.","\u4E00\u5207\u3002"],["A pure atmosphere piece: a quiet corner of the shore.","\u7EAF\u4E3A\u8425\u9020\u6C1B\u56F4\uFF1A\u6D77\u5CB8\u8FB9\u4E00\u5904\u5B89\u9759\u7684\u89D2\u843D\u3002"]),"besiegers-plain":e(["Plain Outside the Walls","\u57CE\u5916\u5E73\u539F"],["The dusty plain where an army pitches its tents before the city.","\u57CE\u524D\u5C18\u571F\u98DE\u626C\u7684\u5E73\u539F\uFF0C\u5927\u519B\u5728\u6B64\u5B89\u8425\u624E\u5BE8\u3002"],["Daenerys's host camped on this plain before the Yellow City.","\u4E39\u59AE\u8389\u4E1D\u7684\u5927\u519B\u66FE\u5728\u9EC4\u57CE\u524D\u7684\u8FD9\u7247\u5E73\u539F\u624E\u8425\u3002"],"medium",["asos"],["Daenerys's army camps before Yunkai; the ground is barely described.","\u4E39\u59AE\u8389\u4E1D\u7684\u519B\u961F\u5728\u6E0A\u51EF\u57CE\u524D\u624E\u8425\uFF1B\u5730\u5F62\u51E0\u4E4E\u672A\u4F5C\u63CF\u5199\u3002"],["Camp layout and distances.","\u8425\u5730\u5E03\u5C40\u4E0E\u8DDD\u79BB\u3002"],["Tents and campfires west of the gate; the layout is invented.","\u897F\u95E8\u4EE5\u897F\u7684\u5E10\u7BF7\u4E0E\u7BDD\u706B\uFF1B\u5E03\u5C40\u4E3A\u81EA\u62DF\u3002"],["Daario's Stormcrows change sides, a night attack routs Yunkai's army, and the Wise Masters free their slaves.","\u8FBE\u91CC\u5965\u7684\u98CE\u66B4\u4E4C\u9E26\u56E2\u5012\u6208\uFF0C\u4E00\u573A\u591C\u88AD\u51FB\u6E83\u6E0A\u51EF\u5927\u519B\uFF0C\u667A\u8005\u968F\u5373\u91CA\u653E\u4E86\u5974\u96B6\u3002"]),"lower-town":e(["Lower Town","\u4E0B\u57CE"],["Rows of flat-roofed yellow houses along grid streets.","\u6CBF\u68CB\u76D8\u8857\u9053\u6392\u5217\u7684\u9EC4\u8272\u5E73\u9876\u623F\u5C4B\u3002"],["An orderly grid of yellow houses: the ordinary city.","\u4E95\u7136\u6709\u5E8F\u7684\u9EC4\u8272\u623F\u5C4B\uFF0C\u4FBF\u662F\u5BFB\u5E38\u5E02\u4E95\u3002"],"low",["asos"],["Ordinary quarters are not described.","\u5BFB\u5E38\u8857\u533A\u672A\u89C1\u63CF\u5199\u3002"],["Everything.","\u4E00\u5207\u3002"],["Houses placed at random, aligned to the grid.","\u623F\u5C4B\u968F\u673A\u5E03\u7F6E\uFF0C\u671D\u5411\u4E0E\u68CB\u76D8\u8857\u9053\u5BF9\u9F50\u3002"])}};export{u as default};
